  g += '<rect x="' + (L + 60) + '" y="' + (H - 15) + '" width="12" height="3" fill="' + COL.today + '"/><text x="' + (L + 76) + '" y="' + (H - 11) + '" font-size="11" fill="' + COL.ink + '">Today</text><rect x="' + (L + 120) + '" y="' + (H - 15) + '" width="12" height="3" fill="' + COL.accent + '"/><text x="' + (L + 136) + '" y="' + (H - 11) + '" font-size="11" fill="' + COL.ink + '">Learned</text>';
