  var h = '<thead><tr><th>Meters</th><th>Pattern</th><th>Who sees gusts first</th><th>Gust match r</th><th>Beats own past</th><th>Speed ratio</th><th>Direction offset</th><th>Geometry says</th></tr></thead><tbody>';
