  var fl = R.fieldLeads(sec), ft = '<thead><tr><th>Meter</th><th>Pattern</th><th>Ahead of the rest</th><th>Match r</th><th>Matches the field now</th><th>Beats the field\'s own past</th><th>Direction shifts</th></tr></thead><tbody>';
